codewords=[(0,0,0,0),(3,1,8,9),(9,5,3,6),(4,6,1,8),(2,3,5,7),(1,8,9,4),(7,2,6,5)]
cs=[[0]+list(v) for v in codewords]
sol=[]
for c in cs:
    week=[]
    for p in range(50):
        x=p%10; y=p//10
        week.append((x+c[y])%10)
    sol+=week
print(len(sol))
