# verify groups sizes and pair repeat
seen={}
ok=True
for w in range(7):
    groups={g:[] for g in range(10)}
    for p in range(50): groups[sol[w*50+p]].append(p)
    if sorted(len(v) for v in groups.values()) != [5]*10:
        print('bad size', w, {k:len(v) for k,v in groups.items()}); ok=False
    for g, players in groups.items():
        for i in range(len(players)):
            for j in range(i+1,len(players)):
                pair=tuple(sorted((players[i],players[j])))
                if pair in seen:
                    print('repeat', pair, 'weeks', seen[pair], w, 'group',g); ok=False; raise SystemExit
                seen[pair]=(w,g)
print('ok',ok,'pairs seen',len(seen))
